def calendar():
    used = {k: {t: 0 for t in TYPE_NAMES} for k in ORDER}
    rows = []
    for d in range(30):
        date = START + datetime.timedelta(days=d)
        for i, key in enumerate(ORDER):
            t = PATTERN[(d - i) % 7]
            n = used[key][t]
            used[key][t] += 1
            title, slug, why = TOPICS[key][t][n]
            rows.append({"day": d + 1, "date": date.isoformat(), "site": key, "type": TYPE_NAMES[t],
                         "title": title, "slug": slug, "why": why, "status": "planned"})
    return rows
